const findings = [
  { id: 'idor-statements', likelihood: 5, impact: 5 },
  { id: 'jwt-in-localstorage', likelihood: 3, impact: 4 },
  { id: 'reset-no-ratelimit', likelihood: 4, impact: 4 },
  { id: 'state-changing-get', likelihood: 2, impact: 3 },
];
let top = findings[0];
let topRisk = -1;
for (const f of findings) {
  const risk = f.likelihood * f.impact;
  if (risk > topRisk) { topRisk = risk; top = f; }
}
console.log('fix-first: ' + top.id + ' risk=' + topRisk);
